import{z as B,x as A,o as t,c as p,q as i,j as n,D as r,d as s,s as l,S as o,b as e}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"优先级反转","description":"","frontmatter":{"title":"优先级反转","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/priority-inversion.md","filePath":"cs/priority-inversion.md","lastUpdated":1791063341000}'),d={name:"cs/priority-inversion.md"};function m(u,a,C,h,D,f){const E=A("Mermaid");return t(),p("div",null,[a[2]||(a[2]=i('<h1 id="优先级反转" tabindex="-1">优先级反转 <a class="header-anchor" href="#优先级反转" aria-label="Permalink to &quot;优先级反转&quot;">​</a></h1><div class="epigraph"><p>低优先级线程占着锁，中优先级线程占着 CPU，高优先级线程忙等或睡眠等锁——优先级在锁上被翻转了。</p><footer>—— 据 Silberschatz et al., Operating System Concepts；火星探路者故障中的优先级反转讨论整理</footer></div><p><a href="/cs/mlfq">上一课</a>让高档任务先跑。一旦共享数据要互斥，低优先级可以持锁；高优先级要同一把锁就只能等。若此时中优先级可运行且不碰那把锁，它会抢走低优先级的 CPU，于是锁迟迟不放，高优先级比中优先级还晚——<strong>优先级反转</strong>。本课只诊断现象，不把继承协议写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>调度器按优先级选 runqueue 队头，它看不见锁。高优先级不是死锁（低优先级最终可能跑完并放锁），但期限可以丢。<a href="/cs/realtime-sched">实时调度对照</a>点过这名字，当时没有锁课。缺口是：在已经有优先级的系统里，<strong>锁把优先级序与逻辑依赖拧反</strong>。本课仍不实现自旋锁，只假设存在互斥。</p><p><span class="marginnote">无界反转：任意多个中优先级可以轮流挡住持锁者。有界反转：只有持锁者自己的剩余临界区，前提是中优先级不能插在持锁者与放锁之间。</span></p><p><span class="marginnote">常见误区：把反转当死锁。死锁的等待图有环、谁也动不了；反转里低优先级最终会跑完放锁，系统没卡死——只是高优先级错过了不该错过的期限。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三线程：\\(L\\) 持锁，\\(H\\) 等锁，\\(M\\) 不碰锁但优先级在二者之间。时间线： \\(L\\) 被 \\(M\\) 抢占 → \\(H\\) 无法前进。对照：若禁止 \\(M\\) 在 \\(L\\) 持锁期间跑（或让 \\(L\\) 暂时等于 \\(H\\) 的优先级），则 \\(H\\) 的等待只剩临界区长度。本课只画清问题，把「暂时抬高」留给下一课。</p>',9)),(t(),n(o,null,{default:r(()=>[l(E,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20L%5B%22%E4%BD%8E%E4%BC%98%E5%85%88%E7%BA%A7%E6%8C%81%E9%94%81%22%5D%20--%3E%20M%5B%22%E4%B8%AD%E4%BC%98%E5%85%88%E7%BA%A7%E5%8D%A0%20CPU%22%5D%0A%20%20H%5B%22%E9%AB%98%E4%BC%98%E5%85%88%E7%BA%A7%E7%AD%89%E9%94%81%22%5D%20--%3E%20L%0A%20%20M%20--%3E%20INV%5B%22H%20%E6%AF%94%20M%20%E8%BF%98%E6%99%9A%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"ISR 里拿锁会把反转变成关中断时间，更难看；那是锁与 IRQ 课的对象。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[s("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"反转说明「优先级」只描述调度器的意愿，不描述资源上的等待图。MLFQ 的档位、实时 FIFO、nice，只要能和锁相遇，都会中招。公平调度的 vruntime 也会因锁而让「该跑的人」跑不成，只是不叫优先级反转而叫锁争用；本课对象是显式优先级。",-1)),a[6]||(a[6]=e("p",null,[e("span",{class:"marginnote"},"直觉类比：急诊室里重病号 H 在等唯一空闲的主治医生 L（他手里拿着病历锁），而普通门诊病人 M 不断插队占用 L 的时间——病不是治不好，是次序被搅乱了。")],-1)),a[7]||(a[7]=e("p",null,"同样三个线程，「放任 M 插队」与「加优先级继承」的等待时长差一个数量级：",-1)),(t(),n(o,null,{default:r(()=>[l(E,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%7B%22M%20%E8%83%BD%E5%90%A6%E6%8F%92%E5%9C%A8%20L%20%E4%B8%8E%E6%94%BE%E9%94%81%E4%B9%8B%E9%97%B4%22%7D%20--%3E%20U%5B%22%E6%97%A0%E7%BB%A7%E6%89%BF%EF%BC%9AM%20%E5%8F%8D%E5%A4%8D%E6%8A%A2%E8%B5%B0%20CPU%22%5D%0A%20%20U%20--%3E%20UB%5B%22H%20%E7%9A%84%E7%AD%89%E5%BE%85%E6%97%A0%E4%B8%8A%E7%95%8C%20%E6%9C%9F%E9%99%90%E5%8F%AF%E4%B8%A2%22%5D%0A%20%20Q%20--%3E%20P%5B%22%E4%BC%98%E5%85%88%E7%BA%A7%E7%BB%A7%E6%89%BF%EF%BC%9AL%20%E4%B8%B4%E6%97%B6%E6%8A%AC%E5%88%B0%20H%20%E7%9A%84%E4%BC%98%E5%85%88%E7%BA%A7%22%5D%0A%20%20P%20--%3E%20PB%5B%22M%20%E6%8A%A2%E4%B8%8D%E8%BF%87%20L%3Cbr%2F%3EH%20%E5%8F%AA%E7%AD%89%E4%B8%B4%E7%95%8C%E5%8C%BA%E5%89%A9%E4%BD%99%E9%95%BF%E5%BA%A6%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=i('<p><span class="marginnote">为什么重要：继承的妙处在于不改调度器、不改锁的实现语义——只是在 H 阻塞在锁上的一瞬间，把持锁者 L 的优先级临时抬到 H 的等级，放锁后还原，插队链条就断了。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把探路者软件的补丁当操作手册，不引入优先级天花板的全部证明。死锁四条件更后；反转的等待图无环也可发生。用户态锁同样能反转，只要内核按优先级调度那些线程。</p><p>后课默认：反转是锁与优先级的结构后果。如何用继承或天花板把等待有界化，下一课讲 PI 与 PCP。</p><p><span class="marginnote">数字实例：1997 年火星探路者在火星上反复重启，正是总线管理线程遭遇优先级反转、被中优先级任务长时间插队放大所致；启用优先级继承后故障消失——教科书概念的真实代价是一台行星探测器。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>反转：低优先级持锁 + 中优先级抢 CPU ⇒ 高优先级被拖。</li><li>不是死锁，但期限可丢；无界时中优先级可一直插队。</li><li>继承与天花板是下一课。</li><li>出处：Silberschatz et al., <em>OSC</em>；实时系统教材中的 PI 案例。</li></ul>',7))])}const _=B(d,[["render",m]]);export{P as __pageData,_ as default};
